// Verify the HMAC signature from the admin, then expand the batch into one
// item per contact.
//
// Uses the Web Crypto API (globalThis.crypto), which is a standard global in
// Node 18+. The Code node sandbox blocks require('crypto') unless n8n is
// started with NODE_FUNCTION_ALLOW_BUILTIN=crypto, so avoid the module.
//
// The signature covers the exact bytes the admin sent, so the raw body is used
// here — re-serializing parsed JSON produces different bytes and never matches.
// The Webhook node must have "Raw Body" enabled.

const cfg = $('Config').first().json;
const secret = (cfg.webhookSecret || '').trim();

const item = $input.first();

// Raw Body arrives as base64 binary; fall back to the parsed body if the
// option is off (unsigned mode only — the bytes will not match a signature).
let raw;
if (item.binary && item.binary.data && item.binary.data.data) {
  const b64 = item.binary.data.data;
  raw = typeof Buffer !== 'undefined'
    ? Buffer.from(b64, 'base64').toString('utf8')
    : new TextDecoder().decode(Uint8Array.from(atob(b64), (c) => c.charCodeAt(0)));
} else {
  raw = JSON.stringify(item.json.body ?? item.json);
}

if (secret) {
  const header = (item.json.headers || {})['x-vermo-signature'] || '';
  const sent = String(header).replace(/^sha256=/, '').toLowerCase();

  const subtle = globalThis.crypto && globalThis.crypto.subtle;
  if (!subtle) {
    throw new Error('Web Crypto is unavailable in this n8n runtime. Either upgrade to Node 18+, or clear webhookSecret in the Config node to disable signature checking.');
  }

  const enc = new TextEncoder();
  const key = await subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sigBuf = await subtle.sign('HMAC', key, enc.encode(raw));
  const expected = Array.from(new Uint8Array(sigBuf))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');

  // Constant-time compare — a plain === leaks how much of the prefix matched.
  let diff = sent.length ^ expected.length;
  for (let i = 0; i < sent.length && i < expected.length; i++) {
    diff |= sent.charCodeAt(i) ^ expected.charCodeAt(i);
  }
  if (diff !== 0) {
    throw new Error('Invalid signature — the payload did not come from the admin dashboard, or the shared secret does not match.');
  }
}

let payload;
try {
  payload = JSON.parse(raw);
} catch (e) {
  throw new Error('Body is not valid JSON: ' + e.message);
}

const contacts = Array.isArray(payload.contacts) ? payload.contacts : [];
if (!contacts.length) {
  return [{ json: { __empty: true, batch: payload.batch || null } }];
}

// One output item per contact, carrying the batch info along for the summary.
return contacts.map((c) => ({
  json: {
    ...c,
    __batch: payload.batch || null,
    __test: !!(payload.batch && payload.batch.test),
  },
}));

// Build the Twenty search filter for this contact.
// Email is the primary key when present; otherwise fall back to phone. A
// contact with neither cannot be matched or created, so it is skipped.
const c = $json;
if (c.__empty) return [];

const email = (c.email || '').trim();
const phone = (c.phoneNumber || '').trim();

let filter = '';
if (email) filter = `emails.primaryEmail[eq]:${email}`;
else if (phone) filter = `phones.primaryPhoneNumber[eq]:${phone}`;

if (!filter) {
  return [{ json: { ...c, __skip: true, __reason: 'no email or phone' } }];
}
return [{ json: { ...c, __filter: filter } }];

// Merge the Twenty lookup result with the original contact and build the
// request body. Emits __action so the IF node can route create vs update.
const contact = $('Build search filter').item.json;
const found = $json?.data?.people?.[0] || null;

const cfg = $('Config').first().json;
const segmentField = (cfg.segmentField || '').trim();
const segmentMode = (cfg.segmentMode || 'text').toLowerCase();

const body = {
  name: { firstName: contact.firstName || '', lastName: contact.lastName || '' },
};

if (contact.email) {
  body.emails = { primaryEmail: contact.email };
}
if (contact.phoneNumber) {
  body.phones = {
    primaryPhoneNumber: contact.phoneNumber,
    primaryPhoneCallingCode: contact.phoneCallingCode || '',
  };
}

// Segments go into a custom field on Person. A Text field takes a joined
// string; a Multi-Select field takes the array of slugs.
const segments = Array.isArray(contact.segments) ? contact.segments : [];
if (segmentField) {
  body[segmentField] = segmentMode === 'multiselect' ? segments : segments.join(', ');
}

return [{
  json: {
    __action: found ? 'update' : 'create',
    __personId: found ? found.id : null,
    __userId: contact.userId,
    __segments: segments,
    body,
  },
}];

// Collapse the per-contact results into one response for the admin.
const items = $input.all();
const results = items.map((i) => {
  const j = i.json || {};
  const person = j?.data?.createPerson || j?.data?.updatePerson || null;
  return {
    personId: person ? person.id : null,
    ok: !!person,
  };
});

const created = results.filter((r) => r.ok).length;
return [{
  json: {
    ok: true,
    received: results.length,
    upserted: created,
    failed: results.length - created,
  },
}];
